#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Lightning strike onto one ground point. The three core components are set up EXACTLY like rpg-game's VFX_BossRaid_Knight_Thunder
    // (art lead 2026-11-04, numbers in .claude/skills/vfx-shader/references/thunder-core.md): line_impact (yellow light column),
    // wave (ground ring) and flare (core flash). Textures may be swapped for others with the same properties (see the Tex* constants).
    // Supporting layers as in the reference: radial ground cracks, white jagged arcs. Everything sits under one group with scale 0.5, as in the reference.
    public static class LightningStrikeBuild
    {
        const string Root = "Assets/VFX/LightningStrike";
        const string Lib = "Assets/VFX/_Imported/RpgGame/Lightning/Textures/";
        const string Thunder = "Assets/VFX/_Imported/RpgThunder/RPG_VFX/";

        // textures: swap these for others with the same properties (sheet / alpha / additive)
        const string TexColumn = Lib + "lightning_texture_sheet1.png";                 // 5x1 sheet, alpha, additive
        const string TexWave = Thunder + "Texture/wave 1.png";                         // ring, alpha blended
        const string TexFlare = Thunder + "Duong/Texture/Mask/TX_VFX_Mask16.png";      // soft round mask, additive
        const string TexCrack = Lib + "T_VFX_Ground_Crack.png";                        // radial cracks, additive
        const string TexArcs = Lib + "HandPaintedLightning2.png";                      // 3x3 sheet of jagged arcs, additive

        [MenuItem("VFX/LightningStrike/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");
            BuildAll();
        }

        public static void BuildBatch() => RunBatch(Build);

        static void BuildAll()
        {
            string M(string part) => Root + "/Materials/M_LightningStrike_" + part + ".mat";
            var mColumn = Material(M("LineImpact"), VfxBlend.Additive, ImportTexture(TexColumn, 1024));
            // wave texture already has a real alpha channel (0..62): do not derive it from grey
            var mWave = Material(M("Wave"), VfxBlend.Alpha, ImportTexture(TexWave, 512));
            var mFlare = Material(M("Flare"), VfxBlend.Additive, ImportTexture(TexFlare, 256));
            var mCrack = Material(M("GroundCrack"), VfxBlend.Additive, ImportTexture(TexCrack, 512));
            var mArcs = Material(M("Arcs"), VfxBlend.Additive, ImportTexture(TexArcs, 512));
            // materials are re-used between builds: always reset tiling / offset (sheets are cut by Texture Sheet Animation only)
            foreach (var m in new[] { mColumn, mWave, mFlare, mCrack, mArcs })
            {
                m.SetTextureScale("_MainTex", Vector2.one); m.SetTextureOffset("_MainTex", Vector2.zero);
                EditorUtility.SetDirty(m);
            }

            // structure (art lead 2026-11-04): VFX name (components), no scale anywhere; the root is itself a Particle System (the flare).
            // The reference's root scale 0.5 is baked into the sizes (size x 0.5 x layer scale); every transform has scale 1
            var root = new GameObject("VFX_LightningStrike");
            var g = root.transform;

            // ---- ground cracks (reference: root "Thunder": size 25, yellow, alpha 0 -> 1 (0.18) -> 1 (0.71) -> 0, life 1)
            var crack = Layer(g, "Cracks", mCrack, life: 1f, duration: 3f, size: 12.5f, color: new Color(1f, 0.86f, 0.23f, 1f), order: -1, rotX: 90f, align: ParticleSystemRenderSpace.Local);
            SetAlpha(crack, 0f, 0f, 0.18f, 1f, 0.71f, 1f, 1f, 0f);
            Bursts(crack, 0f, 1);

            // ---- line_impact: the yellow light column. Stretched Billboard, 3D size (35, 50, 5), pivot (0,1,0): base on the ground, column rises
            var col = Layer(g, "line_impact", mColumn, life: 0.15f, duration: 0.2f, size: 17.5f, color: Color.white, order: 0, rotX: 0f, align: ParticleSystemRenderSpace.View);
            var cm = col.main;
            cm.startSpeed = 0.1f;
            cm.startColor = new ParticleSystem.MinMaxGradient(new Color(1f, 0.804f, 0.035f, 1f), new Color(0.955f, 0.86f, 0.481f, 1f));   // Two Colors: strong yellow .. pale yellow
            cm.startSize3D = true;
            cm.startSizeX = 17.5f; cm.startSizeY = 25f; cm.startSizeZ = 2.5f;
            Bursts(col, 0f, 1, 0.1f, 1);
            var sh = col.shape;
            sh.enabled = true; sh.shapeType = ParticleSystemShapeType.Cone; sh.angle = 0f; sh.radius = 0.0001f; sh.rotation = new Vector3(-90f, 0f, 0f);
            var ts = col.textureSheetAnimation;
            ts.enabled = true; ts.mode = ParticleSystemAnimationMode.Grid; ts.numTilesX = 5; ts.numTilesY = 1;
            ts.animation = ParticleSystemAnimationType.WholeSheet; ts.frameOverTime = Linear(0f, 1f); ts.startFrame = 0f; ts.cycleCount = 1;
            var cg = new Gradient();
            cg.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(new Color(0.96f, 0.95f, 0.96f), 0.27f), new GradientColorKey(new Color(0f, 0.52f, 1f), 0.47f), new GradientColorKey(Color.white, 0.74f) },
                       new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(1f, 0.74f), new GradientAlphaKey(0f, 1f) });
            var col2 = col.colorOverLifetime; col2.enabled = true; col2.color = new ParticleSystem.MinMaxGradient(cg);
            var cr = col.GetComponent<ParticleSystemRenderer>();
            cr.renderMode = ParticleSystemRenderMode.Stretch; cr.lengthScale = 2f; cr.velocityScale = 0f; cr.cameraVelocityScale = 0f;
            cr.pivot = new Vector3(0f, 1f, 0f); cr.flip = new Vector3(0.5f, 0.5f, 0f); cr.maxParticleSize = 5f;

            // ---- wave: ground ring. Billboard, alignment Local, object rotated X -90; size 30, size over life 0.38 -> 1; two beats (t = 0 and 1)
            var wave = Layer(g, "wave", mWave, life: 0.5f, duration: 1.2f, size: 30f, color: new Color(0.98f, 0.93f, 0.42f, 1f), order: 0, rotX: -90f, align: ParticleSystemRenderSpace.Local);
            var wm = wave.main; wm.startDelay = 0.05f; wm.startSize = 30f;   // the reference uses size 30 with Scaling Mode Local (ignores the 0.5 parent); every layer here is Hierarchy, so the size is doubled to keep the same 30 m ring
            Bursts(wave, 0f, 1, 1f, 1);
            var wsz = wave.sizeOverLifetime; wsz.enabled = true; wsz.size = Linear(0.38f, 1f);
            SetAlpha(wave, 0f, 1f, 0.41f, 1f, 1f, 0f);

            // ---- flare: core flash. Billboard, alignment Local, object scale 2; size 15, life 0.3, one particle
            var flare = ParticleOn(root, mFlare, lifetime: 0.3f, size: 15f, color: new Color(1f, 0.91f, 0.57f, 1f));
            var fm = flare.main; fm.duration = 2f; fm.maxParticles = 1;
            var fr = flare.GetComponent<ParticleSystemRenderer>(); fr.alignment = ParticleSystemRenderSpace.Local; fr.sortingOrder = 1; fr.maxParticleSize = 0.5f;
            Bursts(flare, 0f, 1);
            SetAlpha(flare, 0f, 1f, 0.66f, 1f, 1f, 0f);

            // ---- electric_remain: white jagged arcs thrown out in every direction, two beats (t = 0 and 1)
            var arcs = Layer(g, "electric_remain", mArcs, life: 0.35f, duration: 1.2f, size: 3.5f, color: new Color(1f, 1f, 1f, 1f), order: 2, rotX: -90f, align: ParticleSystemRenderSpace.View);
            var am = arcs.main;
            am.startLifetime = new ParticleSystem.MinMaxCurve(0.2f, 0.5f);
            am.startSpeed = new ParticleSystem.MinMaxCurve(0.05f, 0.15f);
            am.startSize = new ParticleSystem.MinMaxCurve(2f, 5f);
            am.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            am.startColor = new ParticleSystem.MinMaxGradient(Color.white, new Color(1f, 0.94f, 0.519f, 1f));
            Bursts(arcs, 0f, 10, 1f, 10);
            var ash = arcs.shape;
            ash.enabled = true; ash.shapeType = ParticleSystemShapeType.Cone; ash.angle = 70f; ash.radius = 0.0001f; ash.randomDirectionAmount = 1f;
            ash.rotation = new Vector3(90f, 0f, 0f);
            var ats = arcs.textureSheetAnimation;
            ats.enabled = true; ats.mode = ParticleSystemAnimationMode.Grid; ats.numTilesX = 3; ats.numTilesY = 3;
            ats.animation = ParticleSystemAnimationType.WholeSheet; ats.frameOverTime = new ParticleSystem.MinMaxCurve(0.9999f); ats.startFrame = new ParticleSystem.MinMaxCurve(0f, 0.888889f);
            SetAlpha(arcs, 0f, 0.05f, 0.15f, 1f, 1f, 0f);
            var ar = arcs.GetComponent<ParticleSystemRenderer>();
            ar.renderMode = ParticleSystemRenderMode.Stretch; ar.lengthScale = 2f; ar.velocityScale = 1f; ar.maxParticleSize = 2f;

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_LightningStrike.prefab");
            var look = new Vector3(0f, 3f, 0f);
            const float d = 22f;
            var cam = look + new Vector3(0f, Mathf.Sin(60f * Mathf.Deg2Rad) * d, -Mathf.Cos(60f * Mathf.Deg2Rad) * d);
            Finish(prefab, Root, "LightningStrike", new[] { 0.04f, 0.1f, 0.2f, 0.4f, 0.8f, 1.1f, 1.5f, 2.2f }, cam, look);
        }

        // ---------------------------------------------------------------- helpers
        static ParticleSystem Layer(Transform parent, string name, Material mat, float life, float duration, float size, Color color, int order, float rotX, ParticleSystemRenderSpace align)
        {
            var ps = Particle(parent, name, mat, lifetime: life, size: size, color: color);
            var main = ps.main; main.duration = duration; main.maxParticles = 1000;
            ps.transform.localRotation = Quaternion.Euler(rotX, 0f, 0f);
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.alignment = align; r.sortingOrder = order; r.maxParticleSize = 5f;
            return ps;
        }

        static void Bursts(ParticleSystem ps, params float[] timeCount)
        {
            var list = new List<ParticleSystem.Burst>();
            for (int i = 0; i < timeCount.Length; i += 2) list.Add(new ParticleSystem.Burst(timeCount[i], (short)timeCount[i + 1]));
            ps.emission.SetBursts(list.ToArray());
        }

        static ParticleSystem.MinMaxCurve Linear(float a, float b)
        {
            var c = new AnimationCurve(new Keyframe(0f, a, b - a, b - a), new Keyframe(1f, b, b - a, b - a));
            return new ParticleSystem.MinMaxCurve(1f, c);
        }

        static void SetAlpha(ParticleSystem ps, params float[] timeValue) => AlphaOverLifetime(ps, timeValue);
    }
}
#endif
